PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?subject_iri
       ?investorId
       ?scenarioRebalanceId
       ?scenario
       ?affectedAssetsSectors
       ?currentAllocationPct
       ?newAllocationPct
       ?rationale
       ?triggeredAction
       ?hasMarketScenario
       ?hasTriggeredAction
       ?sourceTable
       ?rdfs_label
WHERE {
  ?subject_iri a <https://wealth.example.org/ontology/ScenarioRebalancing> .

  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/investorId> ?investorId . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/scenarioRebalanceId> ?scenarioRebalanceId . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/scenario> ?scenario . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/affectedAssetsSectors> ?affectedAssetsSectors . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/currentAllocationPct> ?currentAllocationPct . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/newAllocationPct> ?newAllocationPct . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/rationale> ?rationale . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/triggeredAction> ?triggeredAction . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/hasMarketScenario> ?hasMarketScenario . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/hasTriggeredAction> ?hasTriggeredAction . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/sourceTable> ?sourceTable . }
  OPTIONAL { ?subject_iri rdfs:label ?rdfs_label . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX schema1: <http://schema.org/>
