PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?subject_iri ?investorId ?allocationPct ?totalInvestment ?sector ?sectorAllocationId ?rdfs_label ?sourceTable
WHERE {
  ?subject_iri a <https://wealth.example.org/ontology/SectorAllocation> .
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/investorId> ?investorId . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/allocationPct> ?allocationPct . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/totalInvestment> ?totalInvestment . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/sector> ?sector . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/sectorAllocationId> ?sectorAllocationId . }
  OPTIONAL { ?subject_iri rdfs:label ?rdfs_label . }
  OPTIONAL { ?subject_iri <https://wealth.example.org/ontology/sourceTable> ?sourceTable . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
