PREFIX : <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?subject_iri
       ?investorId
       ?sector
       ?hasCategory
       ?currentValue
       ?cost
       ?investmentName
       ?holdingId
       ?category
       ?rdfs_label
       ?dividends
       ?taxesPaid
       ?returnsPct
       ?purchaseDate
       ?segment
       ?hasSector
       ?hasSegment
       ?hasInvestmentType
       ?sourceTable
WHERE {
  ?subject_iri a <https://wealth.example.org/ontology/PortfolioHolding> .

  OPTIONAL { ?subject_iri :investorId          ?investorId . }
  OPTIONAL { ?subject_iri :sector              ?sector . }
  OPTIONAL { ?subject_iri :hasCategory         ?hasCategory . }
  OPTIONAL { ?subject_iri :currentValue        ?currentValue . }
  OPTIONAL { ?subject_iri :cost                ?cost . }
  OPTIONAL { ?subject_iri :investmentName      ?investmentName . }
  OPTIONAL { ?subject_iri :holdingId           ?holdingId . }
  OPTIONAL { ?subject_iri :category            ?category . }
  OPTIONAL { ?subject_iri rdfs:label           ?rdfs_label . }
  OPTIONAL { ?subject_iri :dividends           ?dividends . }
  OPTIONAL { ?subject_iri :taxesPaid           ?taxesPaid . }
  OPTIONAL { ?subject_iri :returnsPct          ?returnsPct . }
  OPTIONAL { ?subject_iri :purchaseDate        ?purchaseDate . }
  OPTIONAL { ?subject_iri :segment             ?segment . }
  OPTIONAL { ?subject_iri :hasSector           ?hasSector . }
  OPTIONAL { ?subject_iri :hasSegment          ?hasSegment . }
  OPTIONAL { ?subject_iri :hasInvestmentType   ?hasInvestmentType . }
  OPTIONAL { ?subject_iri :sourceTable         ?sourceTable . }
}
